static const char *irc_ui_language(void)
{
    /* Respect the launched program before the compatible shared fallback. */
#ifdef ONEKEY_ONLY
    const char *s = getenv("ONEKEYIRC_LANG");
    if (!s || !*s) s = getenv("VIPIRC_LANG");
#else
    const char *s = getenv("VIPIRC_LANG");
    if (!s || !*s) s = getenv("ONEKEYIRC_LANG");
#endif
    if (!s || !*s) s = getenv("LC_ALL");
    if (!s || !*s) s = getenv("LC_MESSAGES");
    if (!s || !*s) s = getenv("LANG");
    return s && *s ? s : "en";
}
const char *irc_tr(const char *english)
{
    if (!english) return NULL;
    const char *lang = irc_ui_language();
    const IrcTranslation *entries = NULL;
    size_t count = 0;
    if (lang[0] == 'i' && lang[1] == 'd' && (lang[2] == '\0' || lang[2] == '_' || lang[2] == '-' || lang[2] == '.' || lang[2] == '@')) {
        entries = irc_id_table;
        count = sizeof irc_id_table / sizeof irc_id_table[0];
    }
    else if (lang[0] == 'm' && lang[1] == 's' && (lang[2] == '\0' || lang[2] == '_' || lang[2] == '-' || lang[2] == '.' || lang[2] == '@')) {
        entries = irc_ms_table;
        count = sizeof irc_ms_table / sizeof irc_ms_table[0];
    }
    else if (lang[0] == 't' && lang[1] == 'r' && (lang[2] == '\0' || lang[2] == '_' || lang[2] == '-' || lang[2] == '.' || lang[2] == '@')) {
        entries = irc_tr_table;
        count = sizeof irc_tr_table / sizeof irc_tr_table[0];
    }
    else if (lang[0] == 'e' && lang[1] == 's' && (lang[2] == '\0' || lang[2] == '_' || lang[2] == '-' || lang[2] == '.' || lang[2] == '@')) {
        entries = irc_es_table;
        count = sizeof irc_es_table / sizeof irc_es_table[0];
    }
    else if (lang[0] == 'p' && lang[1] == 't' && (lang[2] == '\0' || lang[2] == '_' || lang[2] == '-' || lang[2] == '.' || lang[2] == '@')) {
        entries = irc_pt_table;
        count = sizeof irc_pt_table / sizeof irc_pt_table[0];
    }
    else if (lang[0] == 'f' && lang[1] == 'r' && (lang[2] == '\0' || lang[2] == '_' || lang[2] == '-' || lang[2] == '.' || lang[2] == '@')) {
        entries = irc_fr_table;
        count = sizeof irc_fr_table / sizeof irc_fr_table[0];
    }
    else if (lang[0] == 'd' && lang[1] == 'e' && (lang[2] == '\0' || lang[2] == '_' || lang[2] == '-' || lang[2] == '.' || lang[2] == '@')) {
        entries = irc_de_table;
        count = sizeof irc_de_table / sizeof irc_de_table[0];
    }
    else if (lang[0] == 'r' && lang[1] == 'u' && (lang[2] == '\0' || lang[2] == '_' || lang[2] == '-' || lang[2] == '.' || lang[2] == '@')) {
        entries = irc_ru_table;
        count = sizeof irc_ru_table / sizeof irc_ru_table[0];
    }
    else if (lang[0] == 'i' && lang[1] == 't' && (lang[2] == '\0' || lang[2] == '_' || lang[2] == '-' || lang[2] == '.' || lang[2] == '@')) {
        entries = irc_it_table;
        count = sizeof irc_it_table / sizeof irc_it_table[0];
    }
    else if (lang[0] == 'a' && lang[1] == 'r' && (lang[2] == '\0' || lang[2] == '_' || lang[2] == '-' || lang[2] == '.' || lang[2] == '@')) {
        entries = irc_ar_table;
        count = sizeof irc_ar_table / sizeof irc_ar_table[0];
    }
    if (!entries) return english;
    size_t first = 0, last = count;
    while (first < last) {
        size_t middle = first + (last - first) / 2;
        int comparison = strcmp(english, entries[middle].source);
        if (comparison == 0) return entries[middle].value;
        if (comparison < 0) last = middle;
        else first = middle + 1;
    }
    return english;
}
